def chunks(xs,n):
    for i in range(0,len(xs),n):
        yield i,xs[i:i+n]

def write_in_chunks(spreadsheet_id,sheet_title,start_row,rows,chunk_size=50):
    for off,batch in chunks(rows,chunk_size):
        r1=start_row+off
        r2=r1+len(batch)-1
        a1=f"'{sheet_title}'!A{r1}:D{r2}"
        run_composio_tool('GOOGLESHEETS_UPDATE_VALUES_BATCH',{'spreadsheet_id':spreadsheet_id,'valueInputOption':'USER_ENTERED','data':[{'range':a1,'values':batch,'majorDimension':'ROWS'}]})
